import React from 'react';
import './Hero.css';

export const Hero = () => {
  return (
    <section 
      className="hero-section"
      style={{
        backgroundImage: `url(${process.env.PUBLIC_URL + '/bg%20hero.webp'})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center'
      }}
    >
      <div className="hero-content">
        <h1 className="hero-title">
          The intelligent travel companion<br />
          for <span className="highlight">every journey you take.</span>
        </h1>
        <p className="hero-subtitle">Your journey, our priority. Powered by AI, tailored for you.</p>
        <button className="hero-cta">Join the Beta</button>
      </div>

      <div className="hero-dashboard-wrapper">
        <img src={process.env.PUBLIC_URL + '/hero%20bg%20new.webp'} alt="Dashboard" className="hero-dashboard" />
      </div>

      <div className="hero-foreground-wrapper">
        <img src={process.env.PUBLIC_URL + '/image.webp'} alt="Hills foreground" className="hero-foreground" />
      </div>
    </section>
  );
};
